<style>
.swe-product-detail .swe-breadcrumb{flex-wrap:wrap;row-gap:10px}.swe-product-hero{max-width:950px}.swe-product-detail .swe-schedule-hero h1{font-size:clamp(38px,4.5vw,63px);line-height:1.15;overflow-wrap:anywhere}.swe-product-hero>p{font-size:12px;line-height:1.8;color:#dec2b6}.swe-product-hero>p a{color:#f4dfc5;border-bottom:1px solid #9b766b;padding-bottom:4px}
.swe-product-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:65px;align-items:start}.swe-product-content{min-width:0}.swe-product-visual{aspect-ratio:1.2;background:#eaded1;overflow:hidden;border:1px solid #d8c4b2}.swe-product-visual>img{width:100%;height:100%;object-fit:cover}.swe-product-placeholder{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px;text-align:center;background:linear-gradient(135deg,#eee2d5,#dac7ba)}.swe-product-letter{font-family:'Playfair Display',Georgia,serif;font-size:120px;color:#94616b;line-height:1.5}.swe-product-placeholder>p{font-size:12px;color:#8f6b5e}.swe-product-placeholder>span:last-child{font-size:10px;line-height:1.8;color:#967b6d;margin-top:13px}
.swe-package-description{padding-top:40px;margin-top:35px;border-top:1px solid #ddcfc1}.swe-rich-description,.swe-description-empty{font-size:13px;line-height:2;color:#796969;overflow-wrap:anywhere}.swe-rich-description p{margin-bottom:16px}.swe-rich-description ul{list-style:disc;padding-left:22px;margin-block:16px}.swe-rich-description ol{list-style:decimal;padding-left:22px;margin-block:16px}.swe-rich-description li{margin-block:7px}.swe-rich-description h2,.swe-rich-description h3,.swe-rich-description h4{font-family:'DM Sans',sans-serif;font-size:16px;font-weight:600;letter-spacing:normal;margin:22px 0 12px;color:var(--ink)}.swe-rich-description a{color:var(--wine);text-decoration:underline}.swe-rich-description blockquote{border-left:2px solid #b78a54;padding-left:20px;margin-block:20px}
.swe-purchase-card{background:#f0e6db;border:1px solid #dbc7b6;padding:35px}.swe-product-detail .swe-purchase-card h2{font-size:35px;margin-bottom:25px}.swe-price-block>span{font-size:10px;color:#947663}.swe-price-block>strong{display:block;font-family:'Playfair Display',Georgia,serif;font-size:38px;font-weight:400;line-height:1.3;margin-top:10px;color:var(--wine);overflow-wrap:anywhere}.swe-product-inactive{font-size:12px;color:var(--wine);margin-top:12px}.swe-dp-block{margin-top:22px;padding:18px;border:1px solid #d5bda9;background:#f9f2e9}.swe-dp-block>span{font-size:10px;color:#947663}.swe-dp-block strong{display:block;font-size:16px;margin-top:7px;color:var(--wine)}.swe-dp-block p{font-size:10px;line-height:1.8;margin-top:8px;color:#796969}
.swe-quantity-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #d5bda9;padding-top:23px;margin-top:25px}.swe-quantity-row label{font-size:12px}.swe-quantity-row input{font:inherit;font-size:13px;width:88px;padding:10px 12px;background:#fff;border:1px solid #cdb3a0;border-radius:3px;color:var(--ink)}.swe-quantity-row input:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.swe-quantity-row input:disabled{background:#e9ddd1;color:#8e7567}.swe-quantity-hint{font-size:10px;color:#8b7163;line-height:1.8;margin-top:10px}.swe-subtotal{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:25px 0;border-top:1px solid #d5bda9;padding-top:23px}.swe-subtotal>span{font-size:11px;color:#796969}.swe-subtotal strong{font-size:17px;font-weight:500;color:var(--wine);overflow-wrap:anywhere}
.swe-product-add{width:100%;cursor:pointer}.swe-product-add:disabled{background:#9f827f;color:#fff;cursor:default;transform:none}.swe-product-add:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.swe-product-detail .swe-btn-outline{width:100%;border-color:#bca08e;color:var(--wine);background:transparent;margin-top:12px}.swe-product-detail .swe-btn-outline:hover{background:#faf5ef}.swe-cart-status{font-size:11px;line-height:1.8;color:#77564e;margin-top:12px}.swe-cart-status:empty{display:none}.swe-purchase-note{font-size:10px;color:#8a7164;line-height:1.9;margin-top:20px}
.swe-product-vendor-card{border:1px solid #ddcfc1;padding:28px;margin-top:22px}.swe-product-vendor-card h3{font-family:'Playfair Display',Georgia,serif;font-size:25px;line-height:1.4;margin:15px 0}.swe-product-vendor-card>p{font-size:12px;line-height:1.9;color:#796969}.swe-product-vendor-card .swe-text-link{display:flex;justify-content:space-between;font-size:11px;margin-top:22px}.swe-product-steps{padding-block:65px;background:#eee4da}.swe-product-steps .swe-section-top>p{max-width:320px;margin:0}.swe-order-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:35px}.swe-order-steps article{border-top:1px solid #cdb3a0;padding-top:23px}.swe-order-steps article>span{font-family:Georgia,serif;font-size:26px;color:#aa846b}.swe-order-steps h3{font-size:15px;font-weight:500;margin:18px 0 12px}.swe-order-steps p{font-size:12px;line-height:1.9;color:#796969}
