@media(max-width:767px){.swe-product-detail .swe-schedule-hero h1{font-size:38px}.swe-product-detail .swe-breadcrumb{font-size:10px;gap:10px}.swe-product-layout{grid-template-columns:1fr;gap:30px}.swe-product-content{display:contents}.swe-product-visual{grid-row:1}.swe-product-purchase{grid-row:2}.swe-package-description{grid-row:3;margin-top:0;padding-top:30px}.swe-product-letter{font-size:90px}.swe-product-placeholder{padding:22px}.swe-product-placeholder>.swe-eyebrow{font-size:8px}.swe-purchase-card{padding:26px}.swe-price-block>strong{font-size:35px}.swe-subtotal strong{font-size:17px}.swe-product-steps{padding-block:45px}.swe-product-steps .swe-section-top>p{margin-top:20px}.swe-order-steps{grid-template-columns:1fr;gap:28px}.swe-product-detail .swe-section{padding-block:40px}}
